def main():
    protected={}
    def read(p):
        protected[p.relative_to(GAME).as_posix()]=sha(p)
        return json.loads(p.read_text(encoding='utf-8-sig'))
    p=ROOT/'src/data/feats.js';raw=json.JSONDecoder().raw_decode(p.read_text(encoding='utf-8-sig').split('export const feats = ',1)[1])[0]
    protected[p.relative_to(GAME).as_posix()]=sha(p);by={f['id']:f for f in raw}
    reviewed=set(read(ROOT/'data/public/feat_playtests/manifest.json')['operationalIds'])
    routed={z['featId'] for n in ['CRAFTING_FEAT_INTERFACE_PREPARATION.json','COMBAT_FEAT_SOURCE_PREPARATION.json','SKILL_FEAT_SOURCE_PREPARATION.json','MAGIC_CORE_FEAT_SOURCE_PREPARATION.json'] for z in read(AUDIT/n)['selectedFeats']}
