    selected=[f for f in raw if f['type']=='Magic' and f['id'] not in reviewed|routed]
    assert len(selected)==58 and {f['id'] for f in selected}==set(QUESTIONS)
    rows=[]
    for i,f in enumerate(selected):
        lineage=re.search(r'Prestige lineage: ([^.]+)\.',f['description'])
        rows.append({'featId':f['id'],'questionId':f'MX-{i+1:02}','sourceObject':f,'sourceObjectSha256':digest(f),'fullClauseQuestion':QUESTIONS[f['id']],
          'descriptionLineageLabel':lineage[1] if lineage else None,'lineageGrantsClassAccess':False,'currentOperationalStatus':'full-feat-review-pending',
          'currentAndLegacyEffectIdentical':f['effect']==f.get('legacyEffect'),'currentLiteralPercentageSpans':[{'span':[m.start(),m.end()],'exactText':m.group()} for m in re.finditer(r'\d+(?:\.\d+)?\s*(?:%|percent)',f['effect'])]})
    related=[{'sourceObject':by[id],'sourceObjectSha256':digest(by[id]),'currentOperationalReviewed':id in reviewed,'scope':'complete source counterpart; exact reviewed rules supplied separately where applicable'} for id in RELATED]
    source_spells=read(ROOT/'data/playtest/spell_sources/catalog.json');pub=read(ROOT/'data/public/spell_playtests/catalog.json');pc={s['id']:s for s in pub['spells']}
    ancestry=read(ROOT/'data/public/ancestry_playtests/spells.json')['spells']
    spell_deps=[]
    for name in ['Counterspell','Dispel Magic','Eldritch Blast']:
        hits=[{'id':id,'completeSourceObject':s,'completeCurrentPublicCard':pc[id]} for id,s in source_spells.items() if s['name'].casefold()==name.casefold()]
        anc=[s for s in ancestry if s['name'].casefold()==name.casefold()]
        spell_deps.append({'name':name,'ordinaryMatches':hits,'ancestryOnlyMatches':anc,'exactNameMissing':not hits and not anc,'noAliasInferred':True})
    mirror=read(ROOT/'data/public/class_playtests/mirrorsage.json')
    chosen=['mirrorsage.base.reflective-pulse','mirrorsage.base.reflective-shield','mirrorsage.arch.perfect-reflection','mirrorsage.hero.light-weaver.divine-reflection','mirrorsage.hero.mirror-mage.reflected-repertoire']
    class_deps={'catalogStatus':mirror['status'],'engine':mirror['engine'],'completeCards':[next(c for c in mirror['cards'] if c['id']==id) for id in chosen],'scope':'actual provisional class text; resemblance to a feat does not grant these class features or copy permissions'}
    excerpts=[]
    for name,heads in CONTEXT.items():
        p=ROOT/'docs/mechanics'/name;t=p.read_text(encoding='utf-8');protected[p.relative_to(GAME).as_posix()]=sha(p)
        for h in heads or [None]:excerpts.append({'file':p.relative_to(GAME).as_posix(),'heading':h,'sha256':sha(p),'exactText':section(t,h) if h else t})
    # Preserve observed description/effect conflicts as separate exact fields.
    conflict_ids=['counterspell_adept','runic_shield','mystic_focus','overchannel','lingering_magic','protective_casting','spell_deflection','twin_cast']
    conflicts=[{'featId':id,**{k:by[id][k] for k in ('description','effect','legacyEffect')},'disposition':'pending joint full-clause review; no field silently overwritten'} for id in conflict_ids]
    counts={'sourceFeats':335,'operationalReviewed':8,'pending':327,'selectedMagicExtended':58,'previousMagicCorePrepared':31,'allSourceCategoryMagic':96,'magicCraftingPrepared':2,'magicAlreadyReviewed':5,'otherPendingFocusedPreparation':142,'counterpartRecords':14,'reviewedCounterpartRecords':4,'literalPercentageOccurrences':sum(len(z['currentLiteralPercentageSpans']) for z in rows),'prestigeLineageRecords':sum(z['descriptionLineageLabel'] is not None for z in rows),'observedDescriptionConflicts':len(conflicts),'currentGuideExcerpts':len(excerpts),'classCards':5}
    checks=[
      ('All335 original registry objects preserved',len(raw)==335 and (ROOT/'src/data/feats.js').read_bytes()==(GAME/'src/data/feats.js').read_bytes()),
      ('All327 pending records match earlier source catalog',[f for f in raw if f['id'] not in reviewed]==[z['sourceObject'] for z in pending['records']]),
      ('Exact remaining58 Magic sources',len(selected)==58 and {f['id'] for f in selected}==set(QUESTIONS)),
      ('No overlap with127 routed or8 reviewed',len(routed)==127 and len(reviewed)==8 and not set(QUESTIONS).intersection(routed|reviewed)),
      ('All58 complete source fields and full-clause questions',all(z['sourceObject']==by[z['featId']] and z['sourceObjectSha256']==digest(z['sourceObject']) and len(z['fullClauseQuestion'])>150 for z in rows)),
      ('All96 Magic identities exactly accounted',5+2+31+58==96 and sum(f['type']=='Magic' for f in raw)==96),
      ('Source provisional flags retained, never new approvals',all(z['sourceObject']['status']=='provisional-complete' and z['sourceObject']['needsReview'] and z['sourceObject']['balanceReview'] for z in rows)),
      ('Every current percentage span literal',all(z['sourceObject']['effect'][q['span'][0]:q['span'][1]]==q['exactText'] for z in rows for q in z['currentLiteralPercentageSpans'])),
      ('Eight description conflicts preserved separately',len(conflicts)==8 and all(c['effect']==by[c['featId']]['effect'] for c in conflicts)),
      ('Four reviewed among14 full counterpart sources',len(related)==14 and sum(z['currentOperationalReviewed'] for z in related)==4),
      ('Eldritch Blast exact-name definition absent in two catalogs',next(z for z in spell_deps if z['name']=='Eldritch Blast')['exactNameMissing']),
      ('Five complete class cards, no class access inferred',len(class_deps['completeCards'])==5 and all(not z['lineageGrantsClassAccess'] for z in rows)),
      ('Every governing excerpt is exact',all(z['exactText'] in (GAME/z['file']).read_text(encoding='utf-8') for z in excerpts)),
      ('All protected source and current manuscript files unchanged',all(sha(GAME/q)==h for q,h in protected.items()))]
    assert all(v for _,v in checks),[n for n,v in checks if not v]
    data={'status':'prepared-not-sent; source evidence and questions only','sourceFileSha256':sha(ROOT/'src/data/feats.js'),'selectedFeats':rows,'counterpartSources':related,'spellDependencies':spell_deps,'classDependencies':class_deps,'observedDescriptionConflicts':conflicts,'currentGoverningExcerpts':excerpts,'counts':counts,'checks':[{'name':n,'pass':v} for n,v in checks],'protectedFiles':protected,'featsApproved':0,'newRules':False,'cosmology':'post-push only; preserve pact/plane/soul/lineage words without evaluating their ontology'}
    dump(AUDIT/'MAGIC_EXTENDED_FEAT_SOURCE_PREPARATION.json',data)
    lines=['# Remaining58 Magic feat source questions','',data['status'],'',
      'All remaining58 source-category Magic feats are retained completely, including current effect, description, inactive legacy text and provisional-complete flags. Those flags do not approve expanded operational cards. Eight concrete description/effect conflicts are isolated; the remaining source descriptions are also preserved and must be reconciled during full-clause review.','',
      'These58 plus the earlier31 Magic cohort, two crafting-packet Magic entries and five previously reviewed feats account for all96 Magic-category identities. Every clause remains in scope: multiple attack/defense/teleport/companion clauses are not reduced to the easiest effect. The21 printed prestige-lineage descriptions are labels, not class-acquisition permissions.','',
      'Eldritch Blast has no exact-name definition in the848 ordinary or10 ancestry-only spell catalogs inspected. Forbidden Pact and Eldritch Echo therefore have an explicit spell dependency. Four reviewed counterpart feats retain the full current Buffer Feat rules; ten other counterparts remain pending. The actual Mirrorsage engine and five provisional cards provide finite reflection/copy examples, not automatic aliases.','',
      '| Case | Complete feat | Prerequisite | Full-clause decisions |','|---|---|---|---|']
    for z in rows:
        f=z['sourceObject'];lines.append(f"| {z['questionId']} | {f['name']} ({f['id']}) | {f['prerequisite']} | {z['fullClauseQuestion']} |")
    lines+=['','Review action/rest/round identity, true-HP funding, actual RP pricing, bounded copying/retaliation, real targets and finite resource conservation using supplied rules. Runic Shield needs its own reviewed ward procedure. Time Loop remains unavailable; storing an action or spell does not enable it. Missing component, condition, skill, creature or spell definitions stay explicit.','',
      'Do not discuss or revise cosmology in this source preparation. Keep references to pacts, planes, souls and named entities intact; source-specific mechanics can receive bounded interfaces without deciding their origins. Any decision genuinely requiring cosmology remains deferred until the authorized GitHub push succeeds and its remote commit is verified.','',
      'Prepared only. Finish the active Jewelcrafting conference before another dispatch; refresh relevant dependencies and split this large source packet if needed. No feat approval, source deletion, runtime implementation or human balance claim follows.','']
    audit='\n'.join(lines);write(AUDIT/'MAGIC_EXTENDED_FEAT_SOURCE_AUDIT.md',audit)
    packet='\n\n'.join(['PREPARED REMAINING MAGIC FEAT SOURCE CONFERENCE — NOT SENT.\n58 complete sources,58 individual full-clause questions,14 counterparts,three exact spell lookups and actual current rule dependencies. Source provisional-complete does not establish this operational pass. Preserve current/description/legacy differences and distinguish NEW completions. No cosmology review or Time Loop activation.',audit,'FULL SOURCE AND DEPENDENCY EVIDENCE',json.dumps(data,ensure_ascii=False,separators=(',',':'))])
    p=AUDIT/'CODEX_MAGIC_EXTENDED_FEAT_SOURCE_PREPARED.txt';write(p,packet)
    status={'status':'prepared-not-sent','packetFile':p.name,'characters':len(packet),'packetSha256':sha(p),'counts':counts,'checkCount':len(checks),'protectedFilesUnchanged':len(protected),'featsApproved':0,'sourceInformationDeleted':0,'cosmology':'post-push only'}
    dump(AUDIT/'MAGIC_EXTENDED_FEAT_SOURCE_STATUS.json',status);print(json.dumps(status))
